I’m thinking about creating gRPC server could be very useful with following 

{noformat}syntax = "proto3";

package metricsdoc;

option go_package = "metricsdoc";

// ====================
// Message Definitions
// ====================

// Represents a single classified metric
message MetricInfo {
  string name = 1;         // Metric name (e.g., tidb_query_duration_seconds)
  string description = 2;  // Optional additional description if available
  string help = 3;         // HELP text from Prometheus / Exporter
  string mtype = 4;        // Metric TYPE (counter, gauge, histogram, summary)
  string scope = 5;        // internal | external (classification result)
  string type = 6;         // quantity | quality (classification result)
  string cta = 7;          // informative | actionable (classification result)
  bool reviewed = 8;       // true if human/admin reviewed
  string source = 9;       // Where this metric was scraped from
}

// A collection of classified metrics
message MetricCatalog {
  repeated MetricInfo metrics = 1;
}

// Represents a suggested correction by a developer
message CorrectionRequest {
  string name = 1;               // Metric name
  string suggested_scope = 2;    // Suggested new scope
  string suggested_type = 3;     // Suggested new type
  string suggested_cta = 4;      // Suggested new CTA
}

// Acknowledgment after submitting a correction
message CorrectionResponse {
  string status = 1;
}

// Represents a list of suggested corrections
message Suggestion {
  string name = 1;
  string suggested_scope = 2;
  string suggested_type = 3;
  string suggested_cta = 4;
  string submitted_at = 5;       // Timestamp
}

// Collection of suggestions
message SuggestionCatalog {
  repeated Suggestion suggestions = 1;
}

// Admin approval request
message ApprovalRequest {
  string name = 1;               // Metric to approve
}

// Admin approval response
message ApprovalResponse {
  string status = 1;
}

// Admin update request to manually change classification
message UpdateRequest {
  string name = 1;
  string new_scope = 2;
  string new_type = 3;
  string new_cta = 4;
}

// Admin update response
message UpdateResponse {
  string status = 1;
}

// Reclassification request (re-run AI for a metric)
message ReClassifyRequest {
  string name = 1;               // Metric to reclassify
}

// Reclassification response
message ReClassifyResponse {
  string status = 1;
}

// Empty request for endpoints needing no parameters
message EmptyRequest {}

// Response after warming up (refreshing) metrics
message WarmUpResponse {
  int32 new_metrics_count = 1;
  string status = 2;
}

// ================
// Service Definition
// ================

service MetricsCatalogService {
  // Developers
  rpc GetCatalog(EmptyRequest) returns (MetricCatalog);
  rpc SuggestCorrection(CorrectionRequest) returns (CorrectionResponse);

  // Admins
  rpc ListUnreviewedMetrics(EmptyRequest) returns (MetricCatalog);
  rpc ListSuggestedCorrections(EmptyRequest) returns (SuggestionCatalog);
  rpc ApproveCorrection(ApprovalRequest) returns (ApprovalResponse);
  rpc UpdateMetricClassification(UpdateRequest) returns (UpdateResponse);
  rpc ReClassifyMetric(ReClassifyRequest) returns (ReClassifyResponse);

  // Maintenance
  rpc WarmUpMetrics(EmptyRequest) returns (WarmUpResponse);
}{noformat}

